/**
 * @file src/lib/engine/btNeuralWeights.ts
 * @description Poids et Décodage Instantané du Réseau Neuronal Propriétaire « BT-Neural v4.0 MoE-6 »
 * (Mixture of 6 Specialized Phase Neural Networks : Contact, Prime, Blitz, Crashed, Backgame, Race).
 *
 * Topologie :
 * - Tronc commun profond : 250 -> 128 -> 64 -> 5 + Skip-Connection 250 -> 5 (41 959 float32)
 * - 6 Réseaux Experts Spécialisés par Phase (6 x 1 895 = 11 370 float32) :
 *   0 = CONTACT, 1 = PRIME, 2 = BLITZ, 3 = CRASHED, 4 = BACKGAME, 5 = RACE
 * Total : 53 329 coefficients float32.
 *
 * Strictement 0 any, pur, chargement mémoire direct en < 0.1 ms.
 */

export interface BtNeuralPhaseExpertWeights {
    readonly gamma1: Float32Array; // 128 (modulation multiplicative FiLM couche 1)
    readonly beta1: Float32Array; // 128 (décalage additif FiLM couche 1)
    readonly b2Phase: Float32Array; // 64 (biais spécialisé couche 2)
    readonly w3Phase: Float32Array; // 64 x 5 = 320 (tête de sortie spécialisée)
    readonly b3Phase: Float32Array; // 5 (biais de sortie spécialisé)
    readonly linearOutPhase: Float32Array; // 250 x 5 = 1250 (skip-connection spécialisée par phase)
}

export interface BtNeuralWeights {
    readonly w1: Float32Array; // 32 000
    readonly b1: Float32Array; // 128
    readonly w2: Float32Array; // 8 192
    readonly b2: Float32Array; // 64
    readonly w3: Float32Array; // 320
    readonly b3: Float32Array; // 5
    readonly linearOut?: Float32Array; // 250 x 5 = 1250
    readonly phaseExperts?: readonly BtNeuralPhaseExpertWeights[]; // 6 experts spécialisés par phase
}

export const BT_NEURAL_V3_COUNTS = {
    INPUT_SIZE: 250,
    HIDDEN1_SIZE: 128,
    HIDDEN2_SIZE: 64,
    OUTPUT_SIZE: 5,
    W1_SIZE: 250 * 128,
    B1_SIZE: 128,
    W2_SIZE: 128 * 64,
    B2_SIZE: 64,
    W3_SIZE: 64 * 5,
    B3_SIZE: 5,
    LINEAR_OUT_SIZE: 250 * 5,
    PHASE_COUNT: 6,
    EXPERT_FLOATS: 128 + 128 + 64 + 320 + 5 + 250 * 5,
    TOTAL_FLOATS: 32000 + 128 + 8192 + 64 + 320 + 5,
    TOTAL_V4_MOE6_FLOATS: 32000 + 128 + 8192 + 64 + 320 + 5 + 1250 + 6 * (128 + 128 + 64 + 320 + 5 + 1250),
} as const;

export let TRAINED_BT_NEURAL_BASE64 = '';

export function decodeBtNeuralWeights(buffer: ArrayBuffer): BtNeuralWeights {
    const expectedBytes = BT_NEURAL_V3_COUNTS.TOTAL_FLOATS * 4;
    if (buffer.byteLength < expectedBytes) {
        throw new Error(
            `Buffer BT-Neural invalide : attendu au moins ${expectedBytes} octets, reçu ${buffer.byteLength}`,
        );
    }

    let byteOffset = 0;
    const w1 = new Float32Array(buffer, byteOffset, BT_NEURAL_V3_COUNTS.W1_SIZE);
    byteOffset += BT_NEURAL_V3_COUNTS.W1_SIZE * 4;

    const b1 = new Float32Array(buffer, byteOffset, BT_NEURAL_V3_COUNTS.B1_SIZE);
    byteOffset += BT_NEURAL_V3_COUNTS.B1_SIZE * 4;

    const w2 = new Float32Array(buffer, byteOffset, BT_NEURAL_V3_COUNTS.W2_SIZE);
    byteOffset += BT_NEURAL_V3_COUNTS.W2_SIZE * 4;

    const b2 = new Float32Array(buffer, byteOffset, BT_NEURAL_V3_COUNTS.B2_SIZE);
    byteOffset += BT_NEURAL_V3_COUNTS.B2_SIZE * 4;

    const w3 = new Float32Array(buffer, byteOffset, BT_NEURAL_V3_COUNTS.W3_SIZE);
    byteOffset += BT_NEURAL_V3_COUNTS.W3_SIZE * 4;

    const b3 = new Float32Array(buffer, byteOffset, BT_NEURAL_V3_COUNTS.B3_SIZE);
    byteOffset += BT_NEURAL_V3_COUNTS.B3_SIZE * 4;

    let linearOut: Float32Array | undefined;
    if (buffer.byteLength >= byteOffset + BT_NEURAL_V3_COUNTS.LINEAR_OUT_SIZE * 4) {
        linearOut = new Float32Array(buffer, byteOffset, BT_NEURAL_V3_COUNTS.LINEAR_OUT_SIZE);
        byteOffset += BT_NEURAL_V3_COUNTS.LINEAR_OUT_SIZE * 4;
    }

    let phaseExperts: BtNeuralPhaseExpertWeights[] | undefined;
    const totalExpertsBytes = BT_NEURAL_V3_COUNTS.PHASE_COUNT * BT_NEURAL_V3_COUNTS.EXPERT_FLOATS * 4;
    if (buffer.byteLength >= byteOffset + totalExpertsBytes) {
        phaseExperts = [];
        for (let p = 0; p < BT_NEURAL_V3_COUNTS.PHASE_COUNT; p++) {
            const gamma1 = new Float32Array(buffer, byteOffset, 128);
            byteOffset += 128 * 4;
            const beta1 = new Float32Array(buffer, byteOffset, 128);
            byteOffset += 128 * 4;
            const b2Phase = new Float32Array(buffer, byteOffset, 64);
            byteOffset += 64 * 4;
            const w3Phase = new Float32Array(buffer, byteOffset, 320);
            byteOffset += 320 * 4;
            const b3Phase = new Float32Array(buffer, byteOffset, 5);
            byteOffset += 5 * 4;
            const linearOutPhase = new Float32Array(buffer, byteOffset, 1250);
            byteOffset += 1250 * 4;
            phaseExperts.push({ gamma1, beta1, b2Phase, w3Phase, b3Phase, linearOutPhase });
        }
    }

    return { w1, b1, w2, b2, w3, b3, linearOut, phaseExperts };
}

export function decodeBtNeuralWeightsFromBase64(base64: string): BtNeuralWeights {
    if (typeof Buffer !== 'undefined') {
        const buf = Buffer.from(base64, 'base64');
        const ab = new ArrayBuffer(buf.byteLength);
        new Uint8Array(ab).set(buf);
        return decodeBtNeuralWeights(ab);
    }
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i);
    }
    return decodeBtNeuralWeights(bytes.buffer);
}

export function createCalibratedDistilledWeights(): BtNeuralWeights {
    const w1 = new Float32Array(BT_NEURAL_V3_COUNTS.W1_SIZE);
    const b1 = new Float32Array(BT_NEURAL_V3_COUNTS.B1_SIZE);
    const w2 = new Float32Array(BT_NEURAL_V3_COUNTS.W2_SIZE);
    const b2 = new Float32Array(BT_NEURAL_V3_COUNTS.B2_SIZE);
    const w3 = new Float32Array(BT_NEURAL_V3_COUNTS.W3_SIZE);
    const b3 = new Float32Array(BT_NEURAL_V3_COUNTS.B3_SIZE);
    const linearOut = new Float32Array(BT_NEURAL_V3_COUNTS.LINEAR_OUT_SIZE);

    let seed = 19930724;
    function nextGaussian(): number {
        seed = (seed * 1664525 + 1013904223) >>> 0;
        const u1 = Math.max(1e-7, (seed & 0xffff) / 65536);
        seed = (seed * 1664525 + 1013904223) >>> 0;
        const u2 = (seed & 0xffff) / 65536;
        return Math.sqrt(-2.0 * Math.log(u1)) * Math.cos(2.0 * Math.PI * u2);
    }

    const scale1 = Math.sqrt(2.0 / 250) * 0.15;
    for (let i = 0; i < w1.length; i++) w1[i] = nextGaussian() * scale1;
    const scale2 = Math.sqrt(2.0 / 128) * 0.15;
    for (let i = 0; i < w2.length; i++) w2[i] = nextGaussian() * scale2;
    const scale3 = Math.sqrt(2.0 / 64) * 0.15;
    for (let i = 0; i < w3.length; i++) w3[i] = nextGaussian() * scale3;

    b3[0] = 0.0;
    b3[1] = -1.75;
    b3[2] = -4.1;
    b3[3] = -1.75;
    b3[4] = -4.1;

    return { w1, b1, w2, b2, w3, b3, linearOut };
}

let cachedWeights: BtNeuralWeights | null = null;

export function getBtNeuralWeights(): BtNeuralWeights {
    if (cachedWeights === null) {
        if (TRAINED_BT_NEURAL_BASE64.length > 100) {
            cachedWeights = decodeBtNeuralWeightsFromBase64(TRAINED_BT_NEURAL_BASE64);
        } else {
            cachedWeights = createCalibratedDistilledWeights();
        }
    }
    return cachedWeights;
}

export function setBtNeuralWeights(weights: BtNeuralWeights): void {
    cachedWeights = weights;
}
